function circle_update()
{
	red_ball.position.x = $.width / 2 + circle_params.rotation_radius * Math.cos((circle_params.angle + 180) / 180 * Math.PI);
	red_ball.position.y = $.height / 2 + circle_params.rotation_radius * Math.sin((circle_params.angle + 180) / 180 * Math.PI);
	blue_ball.position.x = $.width / 2 + circle_params.rotation_radius * Math.cos(circle_params.angle / 180 * Math.PI);
	blue_ball.position.y = $.height / 2 + circle_params.rotation_radius * Math.sin(circle_params.angle / 180 * Math.PI);

	for (i = 0; i <= red_ball.radius * 2; i++)
	{
		if (red_tails[i].radius <= 0)
		{
			red_tails[i].position.x = red_ball.position.x;
			red_tails[i].position.y = red_ball.position.y;
			red_tails[i].radius = red_ball.radius;
		}
		else
		{
			red_tails[i].radius -= 0.5;
		}
	}
	for (i = 0; i <= blue_ball.radius * 2; i++)
	{
		if (blue_tails[i].radius <= 0)
		{
			blue_tails[i].position.x = blue_ball.position.x;
			blue_tails[i].position.y = blue_ball.position.y;
			blue_tails[i].radius = blue_ball.radius;
		}
		else
		{
			blue_tails[i].radius -= 0.5;
		}
	}

	if (!last_animation)
	{
		red_circle.x = $.width / 2 + circle_params.rotation_radius * Math.cos((circle_params.angle + 180) / 180 * Math.PI);
		red_circle.y = $.height / 2 + circle_params.rotation_radius * Math.sin((circle_params.angle + 180) / 180 * Math.PI);
		blue_circle.x = $.width / 2 + circle_params.rotation_radius * Math.cos(circle_params.angle / 180 * Math.PI);
		blue_circle.y = $.height / 2 + circle_params.rotation_radius * Math.sin(circle_params.angle / 180 * Math.PI);
	}
	else
	{
		circle_params.angle += 4;

		paper.graphics.clear();
		paper.graphics.beginFill(0xFF0000);
		paper.graphics.drawCircle(red_ball.position.x, red_ball.position.y, red_ball.radius * scale);
		paper.graphics.endFill();

		paper.graphics.beginFill(0x23ACFF);
		paper.graphics.drawCircle(blue_ball.position.x, blue_ball.position.y, blue_ball.radius * scale);
		paper.graphics.endFill();
		for (i = 0; i <= red_ball.radius * 2; i++)
		{
			paper.graphics.beginFill(0xFF0000, 0.2);
			paper.graphics.drawCircle(red_tails[i].position.x, red_tails[i].position.y, red_tails[i].radius * scale);
			paper.graphics.endFill();
		}
		for (i = 0; i <= blue_ball.radius * 2; i++)
		{
			paper.graphics.beginFill(0x23ACFF, 0.2);
			paper.graphics.drawCircle(blue_tails[i].position.x, blue_tails[i].position.y, blue_tails[i].radius * scale);
			paper.graphics.endFill();
		}
	}
}

