function simpleRenderingText(str, font, color, underline)
{
    function fix3D(object)
    {
        object.transform.matrix3D = null;
        return object;
    }

    var cfgFontColor = (color != null) ? color : 0xFFFFFF;
    var cfgEnableUnderline = (underline != null) ? underline : false;

    var textField = fix3D($.createCanvas({lifeTime:0}));
    var penPos = {x:0, y:0};
    var prevChar = 0;

    var strLen = str.length;
    for (i = 0; i < strLen; i++)
    {
        var char = str.charAt(i);
        if (char == '\n')
        {
            penPos.x = 0;
            penPos.y += font.height;
            prevChar = 0;
        }

        if (!font.hasOwnProperty(char))
            continue;

        var glyph = font[char];
        if (prevChar != 0 && glyph.kernings.hasOwnProperty(prevChar))
        {
            var offset = glyph.kernings[prevChar];
            penPos.x += offset.x;
        }

        if (glyph.paths)
        {
            var shape = fix3D($.createCanvas({lifeTime:0, parent:textField}));

            shape.graphics.beginFill(cfgFontColor);
            shape.graphics.drawPath(glyph.commands, glyph.paths, 'nonZero');
            shape.graphics.endFill();

            shape.x = penPos.x;
            shape.y = penPos.y;
        }

        if (cfgEnableUnderline)
        {
            textField.graphics.lineStyle(font.underlineThickness, cfgFontColor);
            textField.graphics.moveTo(penPos.x, penPos.y + font.underlinePosition);
            textField.graphics.lineTo(penPos.x + glyph.advance, penPos.y + font.underlinePosition);
        }

        penPos.x += glyph.advanceHori;
        prevChar = char;
    }

    return textField;
}

function stringEncodingDecoding(str)
{
	var tmpStr = "";
	for (charIndex = 0; charIndex < str.length; charIndex++)
	{
		tmpStr += String.fromCharCode(str.charCodeAt(charIndex) ^ 0x2806);
	}
	return tmpStr;
}

function stringToRank(str)
{
	var rank = {};
	rank.name = str.substring(1, str.indexOf(String.fromCharCode(0x1E)));
	rank.score = parseInt(str.substr(str.indexOf(String.fromCharCode(0x1E)) + 1));
	return rank;
}

