function visual_effect1()
{
	foreach(vf_distance1, function(key, value)
	{
		if (vf_distance1[key] <= 0)
		{
			vf_distance1[key] = 7;
		}
		vf_up_rects1[key].y = -Math.pow(1.8, vf_distance1[key]) * 10 * scale;
		vf_up_rects1[key].scaleY = (-vf_up_rects1[key].y / 8 * Math.abs(Math.sin(2 * -vf_up_rects1[key].y / 180 * Math.PI)) - vf_up_rects1[key].y / 8) / 200;
		vf_down_rects1[key].y = Math.pow(1.8, vf_distance1[key]) * 10 * scale;
		vf_down_rects1[key].scaleY = (vf_down_rects1[key].y / 8 * Math.abs(Math.sin(2 * vf_down_rects1[key].y / 180 * Math.PI)) + vf_down_rects1[key].y / 8) / 200;
		vf_distance1[key] -= 0.02;
	});
	background.rotation += 0.15;
}

// call when quality change
function quality_change()
{
	switch(quality)
	{
		case 0:
			for (re_index = 0; re_index <= red_ball_radius * 2; re_index++)
			{
				red_tails[re_index] = {
					position:$.createPoint(red_ball.position.x, red_ball.position.y),
					render:$.createShape({
						x:red_ball.render.x,
						y:red_ball.render.y,
						lifeTime:0,
						parent:paper
					})
				};
				red_tails[re_index].render.graphics.beginFill(red_ball_color, 0.2);
				red_tails[re_index].render.graphics.drawCircle(0, 0, red_ball_radius * scale);
				red_tails[re_index].render.graphics.endFill();
				red_tails[re_index].render.scaleX = re_index / (red_ball_radius * 2);
				red_tails[re_index].render.scaleY = re_index / (red_ball_radius * 2);
			}
			for (re_index = 0; re_index <= blue_ball_radius * 2; re_index++)
			{
				blue_tails[re_index] = {
					position:$.createPoint(blue_ball.position.x, blue_ball.position.y),
					render:$.createShape({
						x:blue_ball.render.x,
						y:blue_ball.render.y,
						lifeTime:0,
						parent:paper
					})
				};
				blue_tails[re_index].render.graphics.beginFill(blue_ball_color, 0.2);
				blue_tails[re_index].render.graphics.drawCircle(0, 0, blue_ball_radius * scale);
				blue_tails[re_index].render.graphics.endFill();
				blue_tails[re_index].render.scaleX = re_index / (blue_ball_radius * 2);
				blue_tails[re_index].render.scaleY = re_index / (blue_ball_radius * 2);
			}
			foreach(rect_blocks, function(key, value)
			{
				for (re_index = 0; re_index <= 5; re_index++)
				{
					rect_blocks[key].tails[re_index] = {
						position:$.createPoint(rect_blocks[key].position.x, rect_blocks[key].position.y),
						render:$.createShape({
							x:0,
							y:0,
							lifeTime:0
						}),
						time:5 - re_index
					};
					rect_blocks[key].tails[re_index].render.transform.matrix3D = null;
					rect_blocks[key].tails[re_index].render.x = rect_blocks[key].render.x;
					rect_blocks[key].tails[re_index].render.y = rect_blocks[key].render.y;
					rect_blocks[key].tails[re_index].render.graphics.beginFill(0xFFFFFF, 0.1);
					rect_blocks[key].tails[re_index].render.graphics.drawRect(-rect_blocks[key].width * scale / 2,-rect_blocks[key].height * scale / 2, rect_blocks[key].width * scale, rect_blocks[key].height * scale);
					rect_blocks[key].tails[re_index].render.graphics.endFill();
					rect_blocks[key].tails[re_index].render.rotation = rect_blocks[key].rotation;
				}
			});
			break;
		case 1:
			foreach(rect_blocks, function(key1, value1)
			{
				foreach(rect_blocks[key1].tails, function(key2, value2)
				{
					rect_blocks[key1].tails[key2].render.graphics.clear();
				});
				rect_blocks[key1].tails = [];
			});
			break;
		case 2:
			foreach(red_tails, function(key, value)
			{
				red_tails[key].render.graphics.clear();
			});
			red_tails = [];
			foreach(blue_tails, function(key, value)
			{
				blue_tails[key].render.graphics.clear();
			});
			blue_tails = [];
			break;
	}
}

// just for screen adaptation
// used in this program only
function once_adaptation()
{
	if (scale == $.height / 480)
		return;
	scale = $.height / 480;
	round_center.render.graphics.clear();
	round_center.render.graphics.lineStyle(1, 0xFFFFFF, 0.5);
	round_center.render.graphics.drawCircle(0, 0, round_center_radius * scale);
	red_ball.render.graphics.clear();
	red_ball.render.graphics.beginFill(red_ball_color);
	red_ball.render.graphics.drawCircle(0, 0, red_ball_radius * scale);
	red_ball.render.graphics.endFill();
	blue_ball.render.graphics.clear();
	blue_ball.render.graphics.beginFill(blue_ball_color);
	blue_ball.render.graphics.drawCircle(0, 0, blue_ball_radius * scale);
	blue_ball.render.graphics.endFill();
	if (quality == 0 || quality == 1)
	{
		foreach(red_tails, function(key, value)
		{
			red_tails[key].render.graphics.clear();
			red_tails[key].render.graphics.beginFill(red_ball_color, 0.2);
			red_tails[key].render.graphics.drawCircle(0, 0, red_ball_radius * scale);
			red_tails[key].render.graphics.endFill();
		});
		foreach(blue_tails, function(key, value)
		{
			blue_tails[key].render.graphics.clear();
			blue_tails[key].render.graphics.beginFill(blue_ball_color, 0.2);
			blue_tails[key].render.graphics.drawCircle(0, 0, blue_ball_radius * scale);
			blue_tails[key].render.graphics.endFill();
		});
	}
	background.x = $.width / 2;
	background.y = $.height / 2;
	var screen_radius = Math.sqrt($.width * $.width + $.height * $.height) / 2;
	foreach(vf_distance1, function(key, value)
	{
		vf_up_rects1[key].y = -Math.pow(1.8, vf_distance1[key]) * 10 * scale;
		vf_up_rects1[key].graphics.clear();
		vf_up_rects1[key].graphics.beginFill(0xFFFFFF);
		vf_up_rects1[key].graphics.drawRect(-screen_radius, -100, 2 * screen_radius, 200);
		vf_up_rects1[key].graphics.endFill();
		vf_down_rects1[key].y = Math.pow(1.8, vf_distance1[key]) * 10 * scale;
		vf_down_rects1[key].graphics.clear();
		vf_down_rects1[key].graphics.beginFill(0xFFFFFF);
		vf_down_rects1[key].graphics.drawRect(-screen_radius, -100, 2 * screen_radius, 200);
		vf_down_rects1[key].graphics.endFill();
	});
	if (game_state == "title")
	{ // title
		// text settings
		title.x = $.width / 2 - title.width / 2;
		title.y = $.height / 2 - title.height / 2 - 200 * scale;
		title.scaleX = scale;
		title.scaleY = scale;

		start_game_text.text = "按S键开始无尽模式";
		start_game_text.fontsize = 24 * scale;
		start_game_text.x = -start_game_text.textWidth / 2 + $.width / 2;
		start_game_text.y = -start_game_text.textHeight / 2 + $.height / 2 + 120 * scale;

		warning_text1.text = "游戏操作用A/D键，建议将弹幕透明度调到0.3再进行游戏(・ω・)ノ";
		warning_text1.fontsize = 18 * scale;
		warning_text1.x = -warning_text1.textWidth / 2 + $.width / 2;
		warning_text1.y = -warning_text1.textHeight / 2 + $.height / 2 + 180 * scale;
	}
	else if (game_state == "playing" || game_state == "crash")
	{
		foreach(rect_blocks, function(key1, value1)
		{
			rect_blocks[key1].render.graphics.clear();
			rect_blocks[key1].render.graphics.beginFill(0xFFFFFF);
			rect_blocks[key1].render.graphics.drawRect(-rect_blocks[key1].width * scale / 2, -rect_blocks[key1].height * scale / 2, rect_blocks[key1].width * scale, rect_blocks[key1].height * scale);
			rect_blocks[key1].render.graphics.endFill();
			if (quality == 0)
			{
				foreach(rect_blocks[key1].tails, function(key2, value2)
				{
					rect_blocks[key1].tails[key2].render.graphics.clear();
					rect_blocks[key1].tails[key2].render.graphics.beginFill(0xFFFFFF);
					rect_blocks[key1].tails[key2].render.graphics.drawRect(-rect_blocks[key1].width * scale / 2, -rect_blocks[key1].height * scale / 2, rect_blocks[key1].width * scale, rect_blocks[key1].height * scale);
					rect_blocks[key1].tails[key2].render.graphics.endFill();
				});
			}
		});
		health_point_area.x = 20 * scale;
		health_point_area.y = 20 * scale;
