// call when collided
function crashed(crashed_ball)
{
	if (crashed_ball == "red")
	{
		red_ball.render.alpha = 0;
		foreach(red_particles, function(key, value)
		{
			red_particles[key].render.alpha = 1;
			paper.addChild(red_particles[key].render);
			paper.setChildIndex(red_ball.render, paper.numChildren - 1);
			(Tween.tween(red_particles[key].position, {x:value.position.x + Utils.rand(-30, 31)}, {x:value.position.x}, 1, Linear)).play();
			(Tween.tween(red_particles[key].position, {y:value.position.y - Utils.rand(50, 200)}, {y:value.position.y}, 1, Expo)).play();
		});
		if (quality == 0 || quality == 1)
		{
			foreach(red_tails, function(key, value)
			{
				red_tails[key].render.alpha = 0;
			});
		}
	}
	else if (crashed_ball == "blue")
	{
		blue_ball.render.alpha = 0;
		foreach(blue_particles, function(key, value)
		{
			blue_particles[key].render.alpha = 1;
			paper.addChild(blue_particles[key].render);
			paper.setChildIndex(blue_ball.render, paper.numChildren - 1);
			(Tween.tween(blue_particles[key].position, {x:value.position.x + Utils.rand(-30, 31)}, {x:value.position.x}, 1, Linear)).play();
			(Tween.tween(blue_particles[key].position, {y:value.position.y - Utils.rand(50, 200)}, {y:value.position.y}, 1, Expo)).play();
		});
		if (quality == 0 || quality == 1)
		{
			foreach(blue_tails, function(key, value)
			{
				blue_tails[key].render.alpha = 0;
			});
		}
	}
	var red_ball_tween = Tween.tween(red_ball, {angle:180, alpha:1}, {angle:red_ball.angle, alpha:0}, 1, Linear);
	if (blue_ball.angle < 180)
		var blue_ball_tween = Tween.tween(blue_ball, {angle:0, alpha:1}, {angle:blue_ball.angle, alpha:0}, 1, Linear);
	if (blue_ball.angle >= 180)
		var blue_ball_tween = Tween.tween(blue_ball, {angle:360, alpha:1}, {angle:blue_ball.angle, alpha:0}, 1, Linear);
	var crash_parallel = Tween.parallel(red_ball_tween, blue_ball_tween);
	var temp_object = {temp_value:0};
	var temp_tween = Tween.tween(temp_object, {temp_value:0}, {temp_value:0}, 0, Linear);
	var crash_delay = Tween.delay(temp_tween, 1);
	crash_delay.onComplete = function()
	{
		(Tween.tween(distance, {now:distance.prev}, {now:distance.now}, 1, Linear)).play();
		foreach(rect_blocks, function(key, value)
		{
			(Tween.tween(rect_blocks[key].position, {y:value.originHeight}, {y:value.position.y}, 1, Linear)).play();
			if (value.type == "rotation")
			{
				(Tween.tween(rect_blocks[key], {rotation:value.originRotation}, {rotation:value.rotation}, 1, Linear)).play();
			}
			if (value.type == "swing")
			{
				(Tween.tween(rect_blocks[key], {swing_factor:value.originSwing_factor}, {swing_factor:value.swing_factor}, 1, Linear)).play();
			}
			if (value.phantom)
			{
				(Tween.tween(rect_blocks[key], {alpha:1}, {alpha:0}, 1, Linear)).play();
			}
		});
		if (crashed_ball == "red")
		{
			(Tween.tween(red_ball.render, {alpha:1}, {alpha:0}, 1, Linear)).play();
			if (quality == 0 || quality == 1)
			{
				foreach(red_tails, function(key, value)
				{
					(Tween.tween(red_tails[key].render, {alpha:1}, {alpha:0}, 1, Linear)).play();
				});
			}
		}
		else if (crashed_ball == "blue")
		{
			(Tween.tween(blue_ball.render, {alpha:1}, {alpha:0}, 1, Linear)).play();
			if (quality == 0 || quality == 1)
			{
				foreach(blue_tails, function(key, value)
				{
					(Tween.tween(blue_tails[key].render, {alpha:1}, {alpha:0}, 1, Linear)).play();
				});
			}
		}
		foreach(red_particles, function(key, value)
		{
			var tmpTween = Tween.tween(red_particles[key].render, {alpha:0}, {alpha:1}, 1, Linear);
			tmpTween.onComplete = function()
			{
				ScriptManager.popEl(red_particles[key].render);
			};
			tmpTween.play();
		});
		foreach(blue_particles, function(key, value)
		{
			var tmpTween = Tween.tween(blue_particles[key].render, {alpha:0}, {alpha:1}, 1, Linear);
			tmpTween.onComplete = function()
			{
				ScriptManager.popEl(blue_particles[key].render);
			};
			tmpTween.play();
		});
		crash_parallel.play();
	};
	crash_parallel.onComplete = function()
	{
		game_state = "playing";
	};
	crash_delay.play();
}

// call when subtitle change
function subtitle_change(text, fontsize, keep_time)
{
	subtitle.text = text;
	subtitle.fontsize = fontsize * scale;
	subtitle.x = -subtitle.textWidth / 2 + $.width / 2;
	var moving_in = Tween.tween(subtitle, {y:-subtitle.textHeight / 2 + $.height / 2}, {y:-subtitle.textHeight / 2 + $.height / 2 - 30 * scale}, 1.0, Linear);
	var moving_out = Tween.tween(subtitle, {y:-subtitle.textHeight / 2 + $.height / 2 + 30 * scale}, {y:-subtitle.textHeight / 2 + $.height / 2}, 1.0, Linear);
	var alpha_in = Tween.tween(subtitle, {alpha:1}, {alpha:0}, 1.0, Linear);
	var alpha_out = Tween.tween(subtitle, {alpha:0}, {alpha:1}, 1.0, Linear);
	var parallel1 = Tween.parallel(moving_in, alpha_in);
	var parallel2 = Tween.parallel(moving_out, alpha_out);
	var delay1 = Tween.delay(parallel2, keep_time);
	var serial1 = Tween.serial(parallel1, delay1);
	serial1.play();
}

