// collide check function
function collide_checking(_rect_block, _ball)
{
	var rect_block_rotation = Math.floor(_rect_block.rotation) % 360;
	if (rect_block_rotation < 0)
		rect_block_rotation += 360;
	var point1 = $.createPoint(-_rect_block.width / 2 * cosine[rect_block_rotation] - _rect_block.height / 2 * sine[rect_block_rotation] + _rect_block.position.x, -_rect_block.height / 2 * cosine[rect_block_rotation] + _rect_block.width / 2 * sine[rect_block_rotation] + _rect_block.position.y);
	var point2 = $.createPoint(_rect_block.width / 2 * cosine[rect_block_rotation] - _rect_block.height / 2 * sine[rect_block_rotation] + _rect_block.position.x, -_rect_block.height / 2 * cosine[rect_block_rotation] - _rect_block.width / 2 * sine[rect_block_rotation] + _rect_block.position.y);
	var point3 = $.createPoint(-_rect_block.width / 2 * cosine[rect_block_rotation] + _rect_block.height / 2 * sine[rect_block_rotation] + _rect_block.position.x, _rect_block.height / 2 * cosine[rect_block_rotation] + _rect_block.width / 2 * sine[rect_block_rotation] + _rect_block.position.y);
	paper.graphics.lineTo(_ball.position.x * scale + $.width / 2, $.height / 2 - scale * _ball.position.y);
	var vector1 = $.createPoint(point2.x - point1.x, point2.y - point1.y);
	var vector2 = $.createPoint(point3.x - point1.x, point3.y - point1.y);
	var vector3 = $.createPoint(_ball.position.x - point1.x, _ball.position.y - point1.y);
	var projective_length1 = (vector3.x * vector1.x + vector3.y * vector1.y) / vector1.length;
	var projective_length2 = (vector3.x * vector2.x + vector3.y * vector2.y) / vector2.length;
	if (projective_length1 <= vector1.length && projective_length1 >= 0 && projective_length2 <= vector2.length && projective_length2 >= 0)
	{ // collide
		return true;
	}
	else
	{
		return false;
	}
}

// create the block
function createBlock(_position, _width, _height, _type, _phantom, _rotation, _swing_factor)
{
	var new_block = {};
	if (_type == "fake")
	{
		new_block.deltaFakeHeight = Utils.rand(400, 800);
		new_block.fakeHeight = _position.y + new_block.deltaFakeHeight;
		new_block.fakeSpeed = new_block.fakeHeight / ((_position.y + 20) / moving_speed);
		new_block.position = $.createPoint(_position.x, new_block.fakeHeight);
		new_block.originHeight = new_block.fakeHeight;
	}
	else
	{
		new_block.position = _position;
		new_block.originHeight = _position.y;
	}
	new_block.width = _width;
	new_block.height = _height;
	if (_phantom == undefined)
		new_block.phantom = false;
	else
		new_block.phantom = _phantom;
	if (_rotation == undefined)
	{
		if (_type == "rotation")
			new_block.rotation = Math.round(_position.y / moving_speed * rotation_speed) % 180;
		else
			new_block.rotation = 0;
	}
	else
		new_block.rotation = _rotation;
	new_block.rotation_direction = Utils.rand(0, 2); // 0 is clockwise, 1 is anticlockwise
	new_block.originRotation = new_block.rotation;
	if (_swing_factor == undefined)
		new_block.swing_factor = 0;
	else
		new_block.swing_factor = _swing_factor;
	new_block.originSwing_factor = new_block.swing_factor;
	new_block.alpha = 1;
	new_block.type = _type;
	new_block.render = $.createShape({
		x:_position.x * scale + $.width / 2,
		y:$.height / 2 - _position.y * scale,
		lifeTime:0,
		parent:blocks_paper
	});
	new_block.render.graphics.beginFill(0xFFFFFF);
	new_block.render.graphics.drawRect(-new_block.width * scale / 2, -new_block.height * scale / 2, new_block.width * scale, new_block.height * scale);
	new_block.render.graphics.endFill();
	new_block.render.rotation = new_block.rotation;
	new_block.tails = [];
	if (quality == 0)
	{
		for (index = 0; index <= 5; index++)
		{
			new_block.tails[index] = {
				position:$.createPoint(new_block.position.x, new_block.position.y),
				render:$.createShape({
					x:new_block.render.x,
					y:new_block.render.y,
					lifeTime:0,
					parent:blocks_paper
				}),
				time:5 - index
			};
			new_block.tails[index].render.graphics.beginFill(0xFFFFFF, 0.1);
			new_block.tails[index].render.graphics.drawRect(-new_block.width * scale / 2,-new_block.height * scale / 2, new_block.width * scale, new_block.height * scale);
			new_block.tails[index].render.graphics.endFill();
			new_block.tails[index].render.rotation = new_block.rotation;
		}
	}
	return new_block;
}

