function game_over_handle()
{
	player_name = "";
	has_got_name = false;
	ScriptManager.popEl(health_point_area);
	ranking_update();
	if (distance.now > ranks[0].score || distance.now > ranks[1].score || distance.now > ranks[2].score)
		isTop = true;
	else
		isTop = false;
	$.root.addChild(score_area);
	if (isTop)
	{
		score_info.alpha = 1;
		score_info.text = "排名前三\n敢问大角虫名字（发送弹幕回答）";
		score_info.fontsize = 20 * scale;
		score_info.x = $.width - score_info.textWidth - 20;
		score_info.y = $.height / 2 - score_info.textHeight / 2 - 50 * scale;
	}
	else
	{
		copy_code_button.mouseEnabled = false;
		copy_code_button_text.mouseEnabled = copy_code_button_text.selectable = false;
		score_info.alpha = 0;
		copy_code_button.alpha = 0;
		copy_code_button_text.alpha = 0;
	}
	you_text.text = "你的得分：" + distance.now + "点";
	number1_text.text = "No.1：" + ranks[0].name + "   " + ranks[0].score + "点";
	number2_text.text = "No.2：" + ranks[1].name + "   " + ranks[1].score + "点";
	number3_text.text = "No.3：" + ranks[2].name + "   " + ranks[2].score + "点";
	number1_text.fontsize = 24 * scale;
	number1_text.x = 20;
	number1_text.y = $.height / 2 - number1_text.textHeight / 2 - 50 * scale;
	number2_text.fontsize = 24 * scale;
	number2_text.x = 20;
	number2_text.y = $.height / 2 - number2_text.textHeight / 2;
	number3_text.fontsize = 24 * scale;
	number3_text.x = 20;
	number3_text.y = $.height / 2 - number3_text.textHeight / 2 + 50 * scale;
	you_text.fontsize = 24 * scale;
	you_text.x = $.width / 2 - you_text.textWidth / 2;
	you_text.y = $.height / 2 - you_text.textHeight / 2;
	(Tween.tween(score_area, {alpha:1}, {alpha:0}, 1)).play();
	(Tween.tween(paper, {alpha:0}, {alpha:1}, 1)).play();
}

// game logic
function game_logic()
{
	// ball
	red_ball.angle %= 360;
	blue_ball.angle %= 360;

	if (red_ball.angle < 0)
		red_ball.angle += 360;
	if (blue_ball.angle < 0)
		blue_ball.angle += 360;

	var red_ball_angle = Math.floor(red_ball.angle);
	var blue_ball_angle = Math.floor(blue_ball.angle);

	red_ball.position.x = round_center.position.x + round_center_radius * cosine[red_ball_angle];
	red_ball.position.y = round_center.position.y + round_center_radius * sine[red_ball_angle];
	blue_ball.position.x = round_center.position.x + round_center_radius * cosine[blue_ball_angle];
	blue_ball.position.y = round_center.position.y + round_center_radius * sine[blue_ball_angle];

	if (game_state == "title")
	{ // title
		// ball motion
		red_ball.angle -= rotation_speed;
		blue_ball.angle -= rotation_speed;

		// key checking
		if (pressed_key == "S")
		{
			$.root.addChild(health_point_area);
			$.root.setChildIndex(health_point_area, 3);
			health_point_area_tween.play();
			title_tween.onComplete = function()
			{
				ScriptManager.popEl(title);
			};
			title_tween.play();
			start_game_text_tween.onComplete = function()
			{
				ScriptManager.popEl(start_game_text);
			};
			start_game_text_tween.play();
			warning_text1_tween.onComplete = function()
			{
				ScriptManager.popEl(warning_text1);
			};
			warning_text1_tween.play();
			(Tween.tween(round_center.position, {y:-160}, {y:0}, 1, Linear)).play();
			(Tween.tween(red_ball, {angle:180}, {angle:red_ball.angle}, 1, Linear)).play();
			if (blue_ball.angle < 180)
				(Tween.tween(blue_ball, {angle:0}, {angle:blue_ball.angle}, 1, Linear)).play();
			if (blue_ball.angle >= 180)
				(Tween.tween(blue_ball, {angle:360}, {angle:blue_ball.angle}, 1, Linear)).play();
			switch(Utils.rand(0, 5))
			{
				case 0:
					subtitle_change("我想让你自己愿意继续走下去。", 24, 2.0);
					Player.seek(382000);
					timer(createLevel, 4000);
					break;
				case 1:
					subtitle_change("很高兴见到你。\n跟紧我，别碰任何东西。", 24, 4.0);
					Player.seek(391000);
					timer(createLevel, 6000);
					break;
				case 2:
					subtitle_change("我们将迎来新的开始，和新的结局。", 24, 2.0);
					Player.seek(403000);
					timer(createLevel, 4000);
					break;
				case 3:
					subtitle_change("永远不要放弃。", 24, 2.0);
					Player.seek(413000);
					timer(createLevel, 4000);
					break;
				case 4:
					subtitle_change("你必须迈出第一步。", 24, 2.0);
					Player.seek(424000);
					timer(createLevel, 4000);
					break;
			}
			game_state = "playing";
		}
	}
	else if (game_state == "playing")
	{// game
		// key checking
		if (pressed_key == "A")
		{
			red_ball.angle += rotation_speed;
			blue_ball.angle += rotation_speed;
		}
		else if (pressed_key == "D")
		{
			red_ball.angle -= rotation_speed;
			blue_ball.angle -= rotation_speed;
		}

		// hp recover
		if (!hasFinished && health_point < 3.0)
		{
			if (recover_delay_num % recover_delay == 0)
				health_point += 0.01;
			recover_delay_num++;
		}

		// blocks
		foreach(rect_blocks, function(key, value)
		{//block moving and rotate
			if (value.type == "rotation")
			{
				if (value.rotation_direction == 0)
					rect_blocks[key].rotation += rotation_speed;
				else
					rect_blocks[key].rotation -= rotation_speed;
				rect_blocks[key].position.y -= moving_speed;
			}
			else if (value.type == "normal")
			{
				rect_blocks[key].position.y -= moving_speed;
			}
			else if (value.type == "fake")
			{
				if (rect_blocks[key].position.y <= -35)
					rect_blocks[key].position.y -= moving_speed;
				else
					rect_blocks[key].position.y -= value.fakeSpeed;
			}
			else if (value.type == "swing")
			{
				var tmp_swingFactor = value.swing_factor;
				rect_blocks[key].position.x = 80 * sine[tmp_swingFactor];
				rect_blocks[key].swing_factor += 3;
				rect_blocks[key].swing_factor %= 360;
				rect_blocks[key].position.y -= moving_speed;
			}

			if (value.phantom)
			{
				if (value.position.y <= -10 && value.alpha > 0)
				{
					rect_blocks[key].alpha -= 0.1;
				}
			}

			// collide check
			if (collide_checking(value, red_ball))
			{
				$G._set("bgm_time", Player.time);
				Player.seek(366000);
				health_point -= 1.0;
				if (value.phantom)
				{
					rect_blocks[key].alpha = 1;
				}
				// die
				if (health_point <= 0)
				{
					game_state = "game over";
					game_over_handle();
				}
				else
				{
					game_state = "crash";
					crashed("red");
				}
			}
			else
			{
				if (collide_checking(value, blue_ball))
				{
					$G._set("bgm_time", Player.time);
					Player.seek(366000);
					health_point -= 1.0;
					if (value.phantom)
					{
						rect_blocks[key].alpha = 1;
					}
					// die
					if (health_point <= 0)
					{
						game_state = "game over";
						game_over_handle();
					}
					else
					{
						game_state = "crash";
						crashed("blue");
					}
				}
			}
		});

		// distance statistics
		if (!hasFinished && distance_add_delay_num % distance_add_delay == 0)
			distance.now++;
		distance_add_delay_num++;

		// level finished and create new level
		if (!hasFinished && distance.now - distance.prev > distance.level_amount / (moving_speed * distance_add_delay) + 10)
		{
			level++;
			hasFinished = true;
			switch(level)
			{
				case 1: // more blocks
					subtitle_change("更多的障碍", 24, 2.0);
					timer(createLevel, 4000);
					break;
				case 2:
					createLevel();
					break;
				case 3: // speed up
					subtitle_change("速度提升", 24, 2.0);
					timer(createLevel, 4000);
					break;
				case 4: // synthesis 1
					createLevel();
					break;
				case 5:
					createLevel();
					break;
				case 6: // rotation fitness
					subtitle_change("新的障碍：旋转", 24, 2.0);
					timer(createLevel, 4000);
					break;
				case 7: // synthesis 2
					createLevel();
					break;
				case 8:
					createLevel();
					break;
				case 9:
					createLevel();
					break;
				case 10: // rotation crazy
					subtitle_change("注意：前方高能_(:3 」∠)_", 24, 2.0);
					timer(createLevel, 4000);
					break;
				case 11: // swing
					subtitle_change("新的障碍：摇摆", 24, 2.0);
					timer(createLevel, 4000);
					break;
				case 12: // synthesis 3
					createLevel();
					break;
				case 13:
					createLevel();
					break;
				case 14:
					createLevel();
					break;
				case 15:
					createLevel();
					break;
				case 16: // phantom
					subtitle_change("前方核能反应_(:3 」∠)_", 24, 2.0);
					timer(createLevel, 4000);
					break;
				case 17: // permanent loop begin
					subtitle_change("果真装逼高手，是在下输了", 24, 2.0);
					timer(createLevel, 4000);
					break;
				default:
					createLevel();
					break;
			}
		}
	}
	else if (game_state == "game over")
	{
		if (pressed_key == "S")
		{
			var tmpTween2 = Tween.tween(score_area, {alpha:0}, {alpha:1}, 1, Linear);
			tmpTween2.onComplete = function()
			{
				ScriptManager.popEl(score_area);
			};
			tmpTween2.play();
			level = 0;
			distance.now = 0;
			distance.prev = 0;
			distance.level_amount = 0;
			rotation_speed = 4 * 1.2;
			moving_speed = 3 * 1.2;
			health_point = 3.0;
			hasFinished = true;
			paper.alpha = 1;
			foreach(rect_blocks, function(key1, value2)
			{
				rect_blocks[key1].render.graphics.clear();
				ScriptManager.popEl(rect_blocks[key1].render);
				if (quality == 0)
				{
					foreach(rect_blocks[key1].tails, function(key2, value2)
					{
						rect_blocks[key1].tails[key2].render.graphics.clear();
						ScriptManager.popEl(rect_blocks[key1].tails[key2].render);
					});
				}
			});
			rect_blocks = [];
			$.root.addChild(health_point_area);
			$.root.setChildIndex(health_point_area, 3);
			health_point_area_tween.play();
			switch(Utils.rand(0, 5))
			{
				case 0:
					subtitle_change("我想让你自己愿意继续走下去。", 24, 2.0);
					Player.seek(382000);
					timer(createLevel, 4000);
					break;
				case 1:
					subtitle_change("很高兴见到你。\n跟紧我，别碰任何东西。", 24, 4.0);
					Player.seek(391000);
					timer(createLevel, 6000);
					break;
				case 2:
					subtitle_change("我们将迎来新的开始，和新的结局。", 24, 2.0);
					Player.seek(403000);
					timer(createLevel, 4000);
					break;
				case 3:
					subtitle_change("永远不要放弃。", 24, 2.0);
					Player.seek(413000);
					timer(createLevel, 4000);
					break;
				case 4:
					subtitle_change("你必须迈出第一步。", 24, 2.0);
					Player.seek(424000);
					timer(createLevel, 4000);
					break;
			}
			game_state = "playing";
		}
	}
}

// game render
function game_render()
{
	// screen once adaptation
	once_adaptation();

	if (game_state == "playing" || game_state == "crash")
	{// game
		// blocks
		if (quality == 0)
		{
			shock_factor += 10;
			shock_factor %= 360;
		}

		foreach(rect_blocks, function(key1, value1)
		{
			set_render_position(rect_blocks[key1]);
			rect_blocks[key1].render.rotation = rect_blocks[key1].rotation;
			rect_blocks[key1].render.alpha = rect_blocks[key1].alpha;
			if (quality == 0)
			{
				rect_blocks[key1].render.scaleX = 0.05 * sine[shock_factor] + 1;
				rect_blocks[key1].render.scaleY = 0.05 * sine[shock_factor] + 1;
				foreach(rect_blocks[key1].tails, function(key2, value2)
				{
					if (rect_blocks[key1].tails[key2].time <= 0)
					{
						rect_blocks[key1].tails[key2].position.x = rect_blocks[key1].position.x;
						rect_blocks[key1].tails[key2].position.y = rect_blocks[key1].position.y;
						rect_blocks[key1].tails[key2].render.rotation = rect_blocks[key1].render.rotation;
						rect_blocks[key1].tails[key2].render.scaleX = rect_blocks[key1].render.scaleX;
						rect_blocks[key1].tails[key2].render.scaleY = rect_blocks[key1].render.scaleY;
						rect_blocks[key1].tails[key2].time = 5;
					}
					else
					{
						rect_blocks[key1].tails[key2].time -= 1;
					}
					rect_blocks[key1].tails[key2].render.alpha = rect_blocks[key1].alpha;
					set_render_position(rect_blocks[key1].tails[key2]);
				});
			}
		});

		// hp update
		health_point_area_mask.scaleX = 1.0 - health_point / 3.0;
		if (health_point <= 0)
			health_point_area_mask.scaleX = 1.0;

		// distance score update
		distance.now = Math.round(distance.now);
		score_text.text = distance.now;
	}

	// round_center
	set_render_position(round_center);

	// balls
	set_render_position(red_ball);
	set_render_position(blue_ball);

	foreach(red_particles, function(key, value)
	{
		if (game_state != "crash")
		{
			red_particles[key].position.x = red_ball.position.x;
			red_particles[key].position.y = red_ball.position.y;
		}
		set_render_position(red_particles[key]);
	});
	foreach(blue_particles, function(key, value)
	{
		if (game_state != "crash")
		{
			blue_particles[key].position.x = blue_ball.position.x;
			blue_particles[key].position.y = blue_ball.position.y;
		}
		set_render_position(blue_particles[key]);
	});

	// balls' tails
	if (quality == 0 || quality == 1)
	{
		foreach(red_tails, function(key, value)
		{
			if (red_tails[key].render.scaleX < 0 || red_tails[key].render.scaleY < 0)
			{
				red_tails[key].position.x = red_ball.position.x;
				red_tails[key].position.y = red_ball.position.y;
				red_tails[key].render.scaleX = 1.0;
				red_tails[key].render.scaleY = 1.0;
			}
			else
			{
				if (game_state == "playing")
				{
					red_tails[key].position.y -= moving_speed;
				}
				red_tails[key].render.scaleX -= 1.0 / (red_ball_radius * 2);
				red_tails[key].render.scaleY -= 1.0 / (red_ball_radius * 2);
			}
			set_render_position(red_tails[key]);
		});
		foreach(blue_tails, function(key, value)
		{
			if (blue_tails[key].render.scaleX < 0 || blue_tails[key].render.scaleY < 0)
			{
				blue_tails[key].position.x = blue_ball.position.x;
				blue_tails[key].position.y = blue_ball.position.y;
				blue_tails[key].render.scaleX = 1.0;
				blue_tails[key].render.scaleY = 1.0;
			}
			else
			{
				if (game_state == "playing")
				{
					blue_tails[key].position.y -= moving_speed;
				}
				blue_tails[key].render.scaleX -= 1.0 / (blue_ball_radius * 2);
				blue_tails[key].render.scaleY -= 1.0 / (blue_ball_radius * 2);
			}
			set_render_position(blue_tails[key]);
		});
	}

	// visual effects
	if (quality == 0 || quality == 1 || quality == 2)
	{
		if (visual_effect_number != prev_visual_effect_number)
		{
			(Tween.tween(background, {alpha:1}, {alpha:0}, 0.5, Linear)).play();
		}
		switch(visual_effect_number)
		{
			case 1:
				visual_effect1();
				break;
			case 2:
				visual_effect2();
				break;
			default:
				break;
		}
		prev_visual_effect_number = visual_effect_number;
	}
}

// call when key down
function key_down(keyNum)
{
	switch(keyNum)
	{
		case 65: // key A
			pressed_key = "A";
			break;
		case 68: // key D
			pressed_key = "D";
			break;
		case 83: // key S
			pressed_key = "S";
			break;
		case 87: // key W
			if (W_prevent == false)
			{
				switch(quality)
				{
					case 0:
						quality = 1;
						subtitle_change("高质量", 32, 1.0);
						break;
					case 1:
						quality = 2;
						subtitle_change("普通", 32, 1.0);
						break;
					case 2:
						quality = 3;
						subtitle_change("性能优先", 32, 1.0);
						break;
					case 3:
						quality = 0;
						subtitle_change("显卡危机", 32, 1.0);
						break;
				}
				// change quality
				quality_change();
				W_prevent = true;
			}
			break;
	}
}

// call when key up
function key_up(keyNum)
{
	pressed_key = "";
	W_prevent = false;
}

// recover the shape render when player seek frequently
function render_recover()
{
	if ($G._get("seek_complete"))
	{
		foreach(rect_blocks, function(key, value)
		{
			rect_blocks[key].render.graphics.clear();
			rect_blocks[key].render = $.createShape({
				x:0,
				y:0,
				lifeTime:0,
				parent:blocks_paper
			});
			rect_blocks[key].render.transform.matrix3D = null;
			rect_blocks[key].render.x = value.position.x * scale + $.width / 2;
			rect_blocks[key].render.y = $.height / 2 - value.position.y * scale;
			rect_blocks[key].render.graphics.beginFill(0xFFFFFF);
			rect_blocks[key].render.graphics.drawRect(-value.width * scale / 2, -value.height * scale / 2, value.width * scale, value.height * scale);
			rect_blocks[key].render.graphics.endFill();
		});
		if (quality == 0 || quality == 1)
		{
			foreach(red_tails, function(key, value)
			{
				red_tails[key].render.graphics.clear();
				red_tails[key].render = $.createShape({
					x:red_ball.render.x,
					y:red_ball.render.y,
					lifeTime:0,
					parent:paper
				});
				red_tails[key].render.graphics.beginFill(red_ball_color, 0.2);
				red_tails[key].render.graphics.drawCircle(0, 0, red_ball_radius * scale);
				red_tails[key].render.graphics.endFill();
				red_tails[key].render.scaleX = key / (red_ball_radius * 2);
				red_tails[key].render.scaleY = key / (red_ball_radius * 2);
			});
			foreach(blue_tails, function(key, value)
			{
				blue_tails[key].render.graphics.clear();
				blue_tails[key].render = $.createShape({
					x:red_ball.render.x,
					y:red_ball.render.y,
					lifeTime:0,
					parent:paper
				});
				blue_tails[key].render.graphics.beginFill(blue_ball_color, 0.2);
				blue_tails[key].render.graphics.drawCircle(0, 0, red_ball_radius * scale);
				blue_tails[key].render.graphics.endFill();
				blue_tails[key].render.scaleX = key / (red_ball_radius * 2);
				blue_tails[key].render.scaleY = key / (red_ball_radius * 2);
			});
			if (quality == 0)
			{
				foreach(rect_blocks, function(key1, value1)
				{
					foreach(rect_blocks[key1].tails, function(key2, value2)
					{
						rect_blocks[key1].tails[key2].render.graphics.clear();
						rect_blocks[key1].tails[key2].render = $.createShape({
							x:0,
							y:0,
							lifeTime:0,
							parent:blocks_paper
						});
						rect_blocks[key1].tails[key2].render.transform.matrix3D = null;
						rect_blocks[key1].tails[key2].render.x = value1.render.x;
						rect_blocks[key1].tails[key2].render.y = value1.render.y;
						rect_blocks[key1].tails[key2].render.graphics.beginFill(0xFFFFFF, 0.1);
						rect_blocks[key1].tails[key2].render.graphics.drawRect(-value1.width * scale / 2,-value1.height * scale / 2, value1.width * scale, value1.height * scale);
						rect_blocks[key1].tails[key2].render.graphics.endFill();
						rect_blocks[key1].tails[key2].render.rotation = value1.rotation;
					});
				});
			}
		}
		$G._set("seek_complete", false);
	}
}

// call 50 times per second
function main_loop()
{
	render_recover();
	game_logic();
	game_render();
}

// call when game over
var decodingText = "";
function ranking_update()
{
	decodingText = "";
	ranks = [];
	foreach(Player.commentList, function(key, value)
	{
		if (value.pool != 2)
		{
			decodingText = stringEncodingDecoding(value.text);
			if (decodingText.charCodeAt(0) == 0x2 && decodingText.indexOf(String.fromCharCode(0x1E)) != -1)
			{
				ranks.push(stringToRank(decodingText));
			}
		}
	});
	ranks.sort(function(a, b){
		var ascore = a.score;
		var bscore = b.score;
		if (ascore < bscore)
			return 1;
		if (ascore > bscore)
			return -1;
		if (ascore == bscore)
			return 0;
	});
}

function comment_input(data)
{
	if (isTop && game_state == "game over")
	{
		if (has_got_name)
		{
			if ((stringEncodingDecoding(data.text)).charCodeAt(0) == 0x2)
			{
				ranks.push(stringToRank(String.fromCharCode(0x2) + player_name + String.fromCharCode(0x1E) + distance.now));
				ranks.sort(function(a, b)
				{
					return b.score - a.score;
				});
				ranks.pop();
				number1_text.text = "No.1：" + ranks[0].name + "   " + ranks[0].score + "点";
				number2_text.text = "No.2：" + ranks[1].name + "   " + ranks[1].score + "点";
				number3_text.text = "No.3：" + ranks[2].name + "   " + ranks[2].score + "点";
				number1_text.fontsize = 24 * scale;
				number1_text.x = 20;
				number1_text.y = $.height / 2 - number1_text.textHeight / 2 - 50 * scale;
				number2_text.fontsize = 24 * scale;
				number2_text.x = 20;
				number2_text.y = $.height / 2 - number2_text.textHeight / 2;
				number3_text.fontsize = 24 * scale;
				number3_text.x = 20;
				number3_text.y = $.height / 2 - number3_text.textHeight / 2 + 50 * scale;
				copy_code_button.mouseEnabled = false;
				copy_code_button_text.mouseEnabled = copy_code_button_text.selectable = false;
				(Tween.tween(score_info, {alpha:0}, {alpha:1}, 0.2, Linear)).play();
				(Tween.to(copy_code_button, {alpha:0}, 0.2, Linear)).play();
				(Tween.to(copy_code_button_text, {alpha:0}, 0.2, Linear)).play();
			}
		}
		else
		{
			player_name = data.text;
			copy_code_button.mouseEnabled = true;
			copy_code_button_text.mouseEnabled = copy_code_button_text.selectable = true;
			score_info.text = "请点击下方复制按钮";
			score_info.fontsize = 20 * scale;
			score_info.x = $.width - score_info.textWidth - 20;
			score_info.y = $.height / 2 - score_info.textHeight / 2 - 20 * scale;
			copy_code_button.x = $.width / 2 + 220 * scale;
			copy_code_button.y = $.height / 2;
			copy_code_button_text.fontsize = 18 * scale;
			(Tween.tween(copy_code_button, {alpha:0.7}, {alpha:0}, 0.2, Linear)).play();
			(Tween.tween(copy_code_button_text, {alpha:0.7}, {alpha:0}, 0.2, Linear)).play();
			has_got_name = true;
		}
	}
}

function remove_score_info(e)
{
	var comment = e.target;
	if (!comment.hasOwnProperty('data') || !comment.data.hasOwnProperty('text'))
		return;
	if (comment.data.pool != 2)
	{
		decodingText = stringEncodingDecoding(comment.data.text);
		if (decodingText.charCodeAt(0) == 0x2 && decodingText.indexOf(String.fromCharCode(0x1E)) != -1)
		{
			comment.visible = false;
		}
	}
}

